export interface RustOwnedGrpcInvoker {
  invokeGrpc<TRequest, TResponse>(method: RustOwnedGrpcMethodMetadata, request: TRequest): Promise<TResponse>;
  invokeGrpcStream<TRequest, TResponse>(method: RustOwnedGrpcMethodMetadata, request: TRequest): AsyncIterable<TResponse>;
}

export function createStreamGrpcClient(invoker: RustOwnedGrpcInvoker) {
  return {
    inspectIdempotency(request: InspectIdempotencyRequest): Promise<InspectIdempotencyResponse> {
      return invoker.invokeGrpc<InspectIdempotencyRequest, InspectIdempotencyResponse>(STREAM_GRPC_METHODS.inspectIdempotency, request);
    },
    append(request: AppendRequest): Promise<AppendResponse> {
      return invoker.invokeGrpc<AppendRequest, AppendResponse>(STREAM_GRPC_METHODS.append, request);
    },
    tail(request: TailRequest): Promise<TailResponse> {
      return invoker.invokeGrpc<TailRequest, TailResponse>(STREAM_GRPC_METHODS.tail, request);
    },
    fork(request: ForkRequest): Promise<ForkReceipt> {
      return invoker.invokeGrpc<ForkRequest, ForkReceipt>(STREAM_GRPC_METHODS.fork, request);
    },
    read(request: ReadRequest): AsyncIterable<ReadResponse> {
      return invoker.invokeGrpcStream<ReadRequest, ReadResponse>(STREAM_GRPC_METHODS.read, request);
    },
    follow(request: FollowRequest): AsyncIterable<ReadResponse> {
      return invoker.invokeGrpcStream<FollowRequest, ReadResponse>(STREAM_GRPC_METHODS.follow, request);
    },
    children(request: ChildrenRequest): AsyncIterable<ChildrenResponse> {
      return invoker.invokeGrpcStream<ChildrenRequest, ChildrenResponse>(STREAM_GRPC_METHODS.children, request);
    },
    childrenPage(request: ChildrenPageRequest): Promise<ChildrenPageResponse> {
      return invoker.invokeGrpc<ChildrenPageRequest, ChildrenPageResponse>(STREAM_GRPC_METHODS.childrenPage, request);
    },
    commit(request: CommitRequest): Promise<CommitResponse> {
      return invoker.invokeGrpc<CommitRequest, CommitResponse>(STREAM_GRPC_METHODS.commit, request);
    },
    readCommit(request: ReadCommitRequest): Promise<CommittedEnvelope> {
      return invoker.invokeGrpc<ReadCommitRequest, CommittedEnvelope>(STREAM_GRPC_METHODS.readCommit, request);
    },
  } as const;
}

export const STREAM_ROUTES = STREAM_METHODS;

export function interpolateRustOwnedPath(method: RustOwnedMethodMetadata, request: unknown): string {
  let path = method.path;
  for (const parameter of method.pathParameters) {
    const key = parameter === "sha256hex" ? "versionSha256" : parameter;
    const value = (request as Record<string, unknown>)[key];
    if (value === undefined || value === null) throw new TypeError(`missing path parameter ${key}`);
    const rendered = value instanceof Uint8Array ? Array.from(value, byte => byte.toString(16).padStart(2, "0")).join("") : typeof value === "bigint" ? value.toString() : encodeURIComponent(String(value));
    path = path.replace(`{${parameter}}`, rendered);
  }
  return path;
}

export const RUST_OWNED_CREDENTIAL_POLICY = "bearer-no-crlf" as const;

export function validateRustOwnedCredentialPolicy(token: string): void {
  if ((RUST_OWNED_CREDENTIAL_POLICY as string) === "bearer-no-crlf" && validateBearerToken(token) !== "") throw new TypeError("invalid bearer credential");
}

export function validateRustOwnedCredential(method: RustOwnedMethodMetadata, token: string): void {
  if ((method.credentialPolicy as string) === (RUST_OWNED_CREDENTIAL_POLICY as string)) validateRustOwnedCredentialPolicy(token);
}

